"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";

import { lectii } from "../../data/lectii/index";
import { createClient } from "../../lib/supabase/client";
import Mascot from "../../components/Mascot";

type ProgresLectie = {
  id: string;
  titlu: string;
  finalizata: boolean;
  xp: number;
  xpMaxim: number;
  modul: number;
  numarLectie: number;
  totalLectiiModul: number;
  href: string;
};

type ProgresSupabase = {
  lesson_id: string;
  completed: boolean;
  xp: number | null;
};

export default function DashboardPage() {
  const router = useRouter();

  const [supabase] = useState(() => createClient());

  const [nume, setNume] = useState("");
  const [profil, setProfil] = useState("M_mate-info");

  const [progres, setProgres] = useState<ProgresLectie[]>([]);

  const [gata, setGata] = useState(false);
  const [eroareProgres, setEroareProgres] = useState("");
  const [seDeconecteaza, setSeDeconecteaza] =
    useState(false);

  async function deconectare() {
    setSeDeconecteaza(true);

    const { error } = await supabase.auth.signOut();

    if (error) {
      console.error(
        "Eroare la deconectare:",
        error
      );

      setSeDeconecteaza(false);
      return;
    }

    localStorage.removeItem("bac-mate-nume");

    localStorage.removeItem(
      "bac-mate-profil-cod"
    );

    localStorage.removeItem(
      "bac-mate-profil-nume"
    );

    localStorage.removeItem(
      "bac-mate-evaluare-initiala-finalizata"
    );

    router.replace("/cont");
    router.refresh();
  }

  useEffect(() => {
    let activ = true;

    async function incarcaDashboard() {
      setGata(false);
      setEroareProgres("");

      const {
        data: { user },
        error: userError,
      } = await supabase.auth.getUser();

      if (!activ) {
        return;
      }

      if (userError || !user) {
        router.replace("/cont");
        return;
      }

      const {
        data: profilSupabase,
        error: profilError,
      } = await supabase
        .from("profiles")
        .select(
          "nume, profil_bac, evaluare_initiala_finalizata"
        )
        .eq("id", user.id)
        .maybeSingle();

      if (!activ) {
        return;
      }

      if (profilError) {
        console.error(
          "Eroare la încărcarea profilului:",
          profilError
        );

        router.replace("/cont");
        return;
      }

      if (!profilSupabase?.nume) {
        router.replace("/date-personale");
        return;
      }

      if (!profilSupabase.profil_bac) {
        router.replace("/profil");
        return;
      }

      if (
        !profilSupabase.evaluare_initiala_finalizata
      ) {
        router.replace("/evaluare");
        return;
      }

      setNume(profilSupabase.nume);
      setProfil(profilSupabase.profil_bac);

      localStorage.setItem(
        "bac-mate-nume",
        profilSupabase.nume
      );

      localStorage.setItem(
        "bac-mate-profil-cod",
        profilSupabase.profil_bac
      );

      localStorage.setItem(
        "bac-mate-evaluare-initiala-finalizata",
        "da"
      );

      const {
        data: progresSalvat,
        error: progresError,
      } = await supabase
        .from("student_progress")
        .select("lesson_id, completed, xp")
        .eq("user_id", user.id);

      if (!activ) {
        return;
      }

      if (progresError) {
        console.error(
          "Eroare la încărcarea progresului:",
          progresError
        );

        setEroareProgres(
          "Progresul contului nu a putut fi încărcat momentan."
        );

        setGata(true);
        return;
      }

      const progresCloud =
        (progresSalvat ?? []) as ProgresSupabase[];

      /*
       * Considerăm valide doar lecțiile
       * care există în programa actuală.
       */
      const idsLectiiValide = new Set(
        lectii.map((lectie) => lectie.id)
      );

      const progresValid = progresCloud.filter(
        (item) =>
          idsLectiiValide.has(item.lesson_id)
      );

      /*
       * Map rapid:
       * ID lecție -> progresul salvat.
       */
      const progresDupaLectie = new Map<
        string,
        ProgresSupabase
      >();

      progresValid.forEach((item) => {
        progresDupaLectie.set(
          item.lesson_id,
          item
        );
      });

      /*
       * Construim Dashboard-ul folosind
       * registrul oficial al lecțiilor.
       */
      const progresLectii: ProgresLectie[] =
        lectii.map((lectie) => {
          const progresCloudLectie =
            progresDupaLectie.get(lectie.id);

          const finalizata =
            progresCloudLectie?.completed === true;

          const xpSalvat =
            typeof progresCloudLectie?.xp ===
              "number" &&
            Number.isFinite(
              progresCloudLectie.xp
            )
              ? progresCloudLectie.xp
              : 0;

          /*
           * Sistemul actual:
           * un exercițiu corect = 10 XP.
           */
          const xpMaxim =
            lectie.exercitii.length * 10;

          /*
           * XP-ul nu poate fi negativ și
           * nici mai mare decât maximul lecției.
           */
          const xpCorect = Math.max(
            0,
            Math.min(xpSalvat, xpMaxim)
          );

          /*
           * Supabase este sursa oficială.
           *
           * localStorage este sincronizat doar
           * pentru paginile lecțiilor.
           */
          localStorage.setItem(
            lectie.storageKeyXp,
            String(xpCorect)
          );

          if (finalizata) {
            localStorage.setItem(
              lectie.storageKeyFinalizata,
              "da"
            );
          } else {
            localStorage.removeItem(
              lectie.storageKeyFinalizata
            );
          }

          return {
            id: lectie.id,
            titlu: lectie.titlu,
            finalizata,
            xp: xpCorect,
            xpMaxim,
            modul: lectie.modul,
            numarLectie:
              lectie.numarLectie,
            totalLectiiModul:
              lectie.totalLectiiModul,
            href: `/lectii/${lectie.slug}`,
          };
        });

      if (!activ) {
        return;
      }

      setProgres(progresLectii);
      setGata(true);
    }

    incarcaDashboard();

    return () => {
      activ = false;
    };
  }, [router, supabase]);

  /*
   * Numărul total oficial de lecții.
   */
  const totalLectii = lectii.length;

  /*
   * Lecțiile finalizate.
   */
  const lectiiFinalizate = useMemo(() => {
    return progres.filter(
      (lectie) => lectie.finalizata
    ).length;
  }, [progres]);

  /*
   * XP total real.
   */
  const xpTotal = useMemo(() => {
    return progres.reduce(
      (total, lectie) =>
        total + lectie.xp,
      0
    );
  }, [progres]);

  /*
   * XP maxim posibil.
   */
  const xpMaximTotal = useMemo(() => {
    return progres.reduce(
      (total, lectie) =>
        total + lectie.xpMaxim,
      0
    );
  }, [progres]);

  /*
   * Procent progres.
   */
  const procentExact =
    totalLectii === 0
      ? 0
      : (lectiiFinalizate /
          totalLectii) *
        100;

  const procentGeneral =
    Math.round(procentExact * 10) / 10;

  /*
   * Numărul modulelor.
   */
  const numarModule = useMemo(() => {
    return new Set(
      lectii.map(
        (lectie) => lectie.modul
      )
    ).size;
  }, []);

  /*
   * Prima lecție nefinalizată.
   */
  const urmatoareaLectie =
    useMemo(() => {
      if (progres.length === 0) {
        return null;
      }

      return (
        progres.find(
          (lectie) =>
            !lectie.finalizata
        ) ?? null
      );
    }, [progres]);

  /*
   * Detectăm dacă elevul a sărit lecții.
   */
  const existaProgresSarindLectii =
    useMemo(() => {
      if (!urmatoareaLectie) {
        return false;
      }

      const indexUrmatoare =
        progres.findIndex(
          (lectie) =>
            lectie.id ===
            urmatoareaLectie.id
        );

      if (indexUrmatoare < 0) {
        return false;
      }

      return progres
        .slice(indexUrmatoare + 1)
        .some(
          (lectie) =>
            lectie.finalizata ||
            lectie.xp > 0
        );
    }, [
      progres,
      urmatoareaLectie,
    ]);

  const toateFinalizate =
    totalLectii > 0 &&
    lectiiFinalizate ===
      totalLectii;

  /*
   * Progres pe module.
   */
  const progresPeModule =
    useMemo(() => {
      const module = new Map<
        number,
        {
          total: number;
          finalizate: number;
          xp: number;
          xpMaxim: number;
        }
      >();

      progres.forEach((lectie) => {
        const existent =
          module.get(
            lectie.modul
          ) ?? {
            total: 0,
            finalizate: 0,
            xp: 0,
            xpMaxim: 0,
          };

        existent.total += 1;
        existent.xp +=
          lectie.xp;
        existent.xpMaxim +=
          lectie.xpMaxim;

        if (
          lectie.finalizata
        ) {
          existent.finalizate += 1;
        }

        module.set(
          lectie.modul,
          existent
        );
      });

      return Array.from(
        module.entries()
      )
        .sort(
          ([a], [b]) =>
            a - b
        )
        .map(
          ([modul, valori]) => {
            const procent =
              valori.total === 0
                ? 0
                : Math.round(
                    (valori.finalizate /
                      valori.total) *
                      100
                  );

            return {
              modul,
              ...valori,
              procent,
            };
          }
        );
    }, [progres]);

  if (!gata) {
    return (
      <main className="min-h-screen bg-slate-950 text-white">
        <div className="mx-auto max-w-6xl px-6 py-20">
          <p className="text-slate-400">
            Se verifică autentificarea și
            se încarcă progresul...
          </p>
        </div>
      </main>
    );
  }

  if (eroareProgres) {
    return (
      <main className="min-h-screen bg-slate-950 text-white">
        <div className="mx-auto max-w-3xl px-6 py-20">
          <div className="rounded-3xl border border-red-500/30 bg-red-500/10 p-7">
            <p className="text-sm font-black uppercase tracking-wider text-red-400">
              Progres indisponibil
            </p>

            <h1 className="mt-3 text-3xl font-black">
              Nu putem afișa statisticile corect.
            </h1>

            <p className="mt-4 leading-7 text-slate-300">
              {eroareProgres}
            </p>

            <button
              type="button"
              onClick={() =>
                window.location.reload()
              }
              className="mt-6 rounded-xl bg-blue-600 px-5 py-3 font-black hover:bg-blue-500"
            >
              Încearcă din nou
            </button>
          </div>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-slate-950 text-white">
      <header className="border-b border-slate-800">
        <div className="mx-auto flex max-w-6xl items-center justify-between px-6 py-5">
          <a
            href="/"
            className="text-xl font-black"
          >
            BAC{" "}
            <span className="text-blue-500">
              MATE
            </span>
          </a>

          <div className="flex items-center gap-3">
            <a
              href="/programa"
              className="rounded-xl border border-slate-700 px-4 py-2 text-sm font-bold text-slate-300 transition hover:bg-slate-900"
            >
              Programa
            </a>

            <div className="rounded-xl bg-blue-500/10 px-4 py-2 text-sm font-bold text-blue-400">
              {profil}
            </div>

            <button
              type="button"
              onClick={deconectare}
              disabled={
                seDeconecteaza
              }
              className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-2 text-sm font-bold text-red-400 transition hover:bg-red-500/20 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {seDeconecteaza
                ? "Se deconectează..."
                : "Deconectare"}
            </button>
          </div>
        </div>
      </header>

      <div className="mx-auto max-w-6xl px-6 py-12">
        <section>
          <p className="text-sm font-black uppercase tracking-wider text-blue-400">
            Dashboard
          </p>

          <h1 className="mt-3 text-4xl font-black md:text-5xl">
            {nume
              ? `Salut, ${nume} 👋`
              : "Progresul tău la BAC MATE"}
          </h1>

          <p className="mt-4 max-w-3xl text-lg leading-8 text-slate-400">
            Progresul afișat aici este
            sincronizat cu contul tău BAC
            MATE.
          </p>
        </section>

        {/* MASCOT V1 */}

        <section className="mt-8">
          <Mascot
            mood={
              lectiiFinalizate > 0
                ? "happy"
                : "encouraging"
            }
            studentName={nume}
            message={
              toateFinalizate
                ? "Ai parcurs toate lecțiile BAC MATE. Următorul nostru obiectiv este să menținem materia proaspătă prin recapitulare și verificări periodice."
                : urmatoareaLectie
                  ? `Am analizat progresul tău. Următorul pas recomandat este „${urmatoareaLectie.titlu}”. Putem continua de acolo.`
                  : "Sunt aici să te ajut să îți organizezi pregătirea pentru BAC."
            }
          />
        </section>

        {/* CARDURI PRINCIPALE */}

        <section className="mt-10 grid gap-5 md:grid-cols-4">
          <div className="rounded-3xl border border-slate-800 bg-slate-900 p-6">
            <p className="text-sm font-bold text-slate-400">
              Progres general
            </p>

            <p className="mt-3 text-4xl font-black">
              {procentGeneral}%
            </p>

            <p className="mt-2 text-sm text-slate-500">
              {lectiiFinalizate} din{" "}
              {totalLectii} lecții
            </p>
          </div>

          <div className="rounded-3xl border border-slate-800 bg-slate-900 p-6">
            <p className="text-sm font-bold text-slate-400">
              Lecții finalizate
            </p>

            <p className="mt-3 text-4xl font-black text-emerald-400">
              {lectiiFinalizate}
            </p>

            <p className="mt-2 text-sm text-slate-500">
              Salvate în contul tău
            </p>
          </div>

          <div className="rounded-3xl border border-slate-800 bg-slate-900 p-6">
            <p className="text-sm font-bold text-slate-400">
              XP total
            </p>

            <p className="mt-3 text-4xl font-black text-amber-400">
              {xpTotal}
            </p>

            <p className="mt-2 text-sm text-slate-500">
              din maximum{" "}
              {xpMaximTotal} XP
            </p>
          </div>

          <div className="rounded-3xl border border-slate-800 bg-slate-900 p-6">
            <p className="text-sm font-bold text-slate-400">
              Lecții disponibile
            </p>

            <p className="mt-3 text-4xl font-black text-blue-400">
              {totalLectii}
            </p>

            <p className="mt-2 text-sm text-slate-500">
              {numarModule} module BAC
              MATE
            </p>
          </div>
        </section>

        {/* PROGRES TOTAL */}

        <section className="mt-8 rounded-3xl border border-slate-800 bg-slate-900 p-7">
          <div className="flex items-center justify-between gap-4">
            <div>
              <p className="text-sm font-black uppercase tracking-wider text-blue-400">
                Progres total
              </p>

              <h2 className="mt-2 text-2xl font-black">
                {lectiiFinalizate}/
                {totalLectii} lecții
              </h2>
            </div>

            <p className="text-2xl font-black">
              {procentGeneral}%
            </p>
          </div>

          <div className="mt-5 h-4 overflow-hidden rounded-full bg-slate-800">
            <div
              className="h-full rounded-full bg-blue-500 transition-all"
              style={{
                width: `${Math.min(
                  100,
                  procentExact
                )}%`,
              }}
            />
          </div>
        </section>

        {/* URMĂTOAREA LECȚIE */}

        {urmatoareaLectie && (
          <section className="mt-8 rounded-3xl border border-blue-500/30 bg-blue-500/5 p-7">
            <p className="text-sm font-black uppercase tracking-wider text-blue-400">
              {existaProgresSarindLectii
                ? "Următoarea lecție recomandată"
                : "Continuă de aici"}
            </p>

            <h2 className="mt-3 text-2xl font-black md:text-3xl">
              {
                urmatoareaLectie.titlu
              }
            </h2>

            <p className="mt-3 text-slate-300">
              Modul{" "}
              {urmatoareaLectie.modul} •
              Lecția{" "}
              {
                urmatoareaLectie.numarLectie
              }{" "}
              din{" "}
              {
                urmatoareaLectie.totalLectiiModul
              }
            </p>

            {existaProgresSarindLectii && (
              <p className="mt-3 max-w-3xl text-sm leading-6 text-slate-400">
                Ai progres și în lecții
                aflate mai târziu în programă.
                Îți recomandăm această lecție
                pentru a completa traseul în
                ordine.
              </p>
            )}

            <a
              href={
                urmatoareaLectie.href
              }
              className="mt-5 inline-block rounded-xl bg-blue-600 px-6 py-4 font-black transition hover:bg-blue-500"
            >
              Deschide lecția →
            </a>
          </section>
        )}

        {toateFinalizate && (
          <section className="mt-8 rounded-3xl border border-emerald-500/30 bg-emerald-500/10 p-7">
            <p className="text-3xl font-black">
              🎉 Ai terminat toate lecțiile!
            </p>

            <p className="mt-3 text-slate-300">
              Ai parcurs întregul traseu
              BAC MATE.
            </p>
          </section>
        )}

        {/* PROGRES PE MODULE */}

        <section className="mt-10">
          <p className="text-sm font-black uppercase tracking-wider text-blue-400">
            Progres pe module
          </p>

          <h2 className="mt-2 text-3xl font-black">
            Unde te afli în programă
          </h2>

          <div className="mt-6 grid gap-5 md:grid-cols-2">
            {progresPeModule.map(
              (modul) => (
                <div
                  key={
                    modul.modul
                  }
                  className="rounded-3xl border border-slate-800 bg-slate-900 p-6"
                >
                  <div className="flex items-center justify-between gap-5">
                    <div>
                      <p className="text-sm font-bold text-blue-400">
                        MODUL{" "}
                        {modul.modul}
                      </p>

                      <p className="mt-1 text-xl font-black">
                        {
                          modul.finalizate
                        }
                        /
                        {modul.total}{" "}
                        finalizate
                      </p>

                      <p className="mt-2 text-sm text-amber-400">
                        ⭐{" "}
                        {modul.xp} XP
                      </p>
                    </div>

                    <p className="text-2xl font-black">
                      {
                        modul.procent
                      }
                      %
                    </p>
                  </div>

                  <div className="mt-5 h-3 overflow-hidden rounded-full bg-slate-800">
                    <div
                      className="h-full rounded-full bg-emerald-500 transition-all"
                      style={{
                        width: `${modul.procent}%`,
                      }}
                    />
                  </div>
                </div>
              )
            )}
          </div>
        </section>

        {/* ISTORIC */}

        <section className="mt-10 rounded-3xl border border-slate-800 bg-slate-900 p-7">
          <p className="text-sm font-black uppercase tracking-wider text-blue-400">
            Lecțiile tale
          </p>

          <h2 className="mt-2 text-3xl font-black">
            Istoric și progres
          </h2>

          <div className="mt-6 space-y-3">
            {progres.map(
              (lectie) => (
                <a
                  key={lectie.id}
                  href={
                    lectie.href
                  }
                  className="flex items-center gap-4 rounded-2xl border border-slate-800 bg-slate-950 p-4 transition hover:border-slate-700"
                >
                  <div
                    className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl font-black ${
                      lectie.finalizata
                        ? "bg-emerald-500/10 text-emerald-400"
                        : "bg-slate-900 text-slate-500"
                    }`}
                  >
                    {lectie.finalizata
                      ? "✓"
                      : lectie.numarLectie}
                  </div>

                  <div className="min-w-0 flex-1">
                    <p className="font-bold">
                      {
                        lectie.titlu
                      }
                    </p>

                    <p className="mt-1 text-sm text-slate-500">
                      Modul{" "}
                      {lectie.modul} •{" "}
                      {lectie.xp}/
                      {
                        lectie.xpMaxim
                      }{" "}
                      XP
                    </p>
                  </div>

                  <div
                    className={`text-sm font-black ${
                      lectie.finalizata
                        ? "text-emerald-400"
                        : lectie.xp > 0
                          ? "text-amber-400"
                          : "text-slate-500"
                    }`}
                  >
                    {lectie.finalizata
                      ? "Finalizată"
                      : lectie.xp > 0
                        ? "În progres"
                        : "De parcurs"}
                  </div>
                </a>
              )
            )}
          </div>
        </section>

        <div className="mt-8 flex flex-col gap-3 sm:flex-row">
          <a
            href="/programa"
            className="rounded-xl bg-blue-600 px-6 py-4 text-center font-black transition hover:bg-blue-500"
          >
            Vezi programa →
          </a>

          <a
            href="/evaluare"
            className="rounded-xl border border-slate-700 px-6 py-4 text-center font-black transition hover:bg-slate-900"
          >
            Refă evaluarea
          </a>
        </div>
      </div>
    </main>
  );
}